function t(key,vars={}){let value=I18N[state.lang]?.[key]??I18N.ro[key]??key;return String(value).replace(/\{(\w+)\}/g,(_,k)=>vars[k]??'')}
function getPreferredLanguage(){const saved=localStorage.getItem('taskflow-language');if(saved==='ro'||saved==='en')return saved;return 'ro'}
function locale(){return state.lang==='en'?'en-GB':'ro-RO'}
function countTasksText(n){return `${n} ${n===1?t('task_count_one'):t('task_count_many')}`}
function statusLabel(status){return t(`status_${String(status).replace(/ /g,'_')}`)}
function priorityLabel(priority){return t(`priority_${priority}`)}
function projectGroupLabel(group){return ({'Linii de Producție':t('production_lines'),'Proiecte Fabrică':t('factory_projects'),'Proiecte Globale':t('global_projects'),'Palantir':'Palantir'})[group]||group}
function commentTypeLabel(type){return ({progress:t('comment_progress'),note:t('comment_note'),blocker:t('comment_blocker'),decision:t('comment_decision')})[type]||type}
function fieldLabel(field){return t(`field_${field}`)}
function historyValue(field,value){if(!value)return '—';if(field==='status')return statusLabel(value);if(field==='priority')return priorityLabel(value);if(field==='project_group')return projectGroupLabel(value);return value}
function applyStaticTranslations(){
  document.documentElement.lang=state.lang;
  document.querySelectorAll('[data-i18n]').forEach(node=>{node.textContent=t(node.dataset.i18n)});
  document.querySelectorAll('[data-i18n-placeholder]').forEach(node=>{node.placeholder=t(node.dataset.i18nPlaceholder)});
  document.querySelectorAll('[data-i18n-title]').forEach(node=>{node.title=t(node.dataset.i18nTitle)});
  document.querySelectorAll('[data-i18n-aria]').forEach(node=>{node.setAttribute('aria-label',t(node.dataset.i18nAria))});
  if(el.languageLabel)el.languageLabel.textContent=state.lang==='ro'?'EN':'RO';
  if(el.languageToggle){el.languageToggle.title=t('language_switch');el.languageToggle.setAttribute('aria-label',t('language_switch'))}
}
function applyLanguage(lang,persist=false){
  state.lang=lang==='en'?'en':'ro';if(persist)localStorage.setItem('taskflow-language',state.lang);
  applyStaticTranslations();applyTheme(document.documentElement.dataset.theme||getPreferredTheme(),false);
  if(state.syncKey)setSync(t(state.syncKey),el.syncBadge?.dataset.state||'');
  renderAll();
  if(el.taskDialog?.open){const status=el.taskStatus.value,priority=el.taskPriority.value,group=el.taskProjectGroup.value,project=el.taskProject.value;el.taskDialogTitle.textContent=el.taskId.value?t('edit_task_title'):t('new_task');renderTaskFormOptions(status,priority,group,project)}
  if(el.detailDialog?.open&&state.detailTaskId)openDetail(state.detailTaskId);
}
function toggleLanguage(){applyLanguage(state.lang==='ro'?'en':'ro',true)}

function getPreferredTheme(){
  const saved=localStorage.getItem('taskflow-theme');
  if(saved==='dark'||saved==='light')return saved;
  return window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';
}
function applyTheme(theme,persist=false){
  document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;
  if(el.themeIcon)el.themeIcon.textContent=theme==='dark'?'☀':'☾';
  if(el.themeLabel)el.themeLabel.textContent=theme==='dark'?t('light'):t('dark');
  if(el.themeToggle){el.themeToggle.title=theme==='dark'?t('theme_to_light'):t('theme_to_dark');el.themeToggle.setAttribute('aria-label',el.themeToggle.title)}
  const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',theme==='dark'?'#0b1120':'#0f172a');
  if(persist)localStorage.setItem('taskflow-theme',theme);
}
function toggleTheme(){applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true)}
state.lang=getPreferredLanguage();
applyTheme(getPreferredTheme());

function uid(){return crypto.randomUUID ? crypto.randomUUID() : `id-${Date.now()}-${Math.random().toString(16).slice(2)}`}
function nowISO(){return new Date().toISOString()}
function todayISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function safeJson(v,fallback=[]){try{const x=JSON.parse(v||'');return x??fallback}catch{return fallback}}
function fmtDate(iso){if(!iso)return '—';const d=new Date(`${iso}T12:00:00`);return Number.isNaN(d.getTime())?iso:d.toLocaleDateString(locale(),{day:'2-digit',month:'short',year:'2-digit'})}
function fmtDateTime(iso){if(!iso)return '—';const d=new Date(iso);return Number.isNaN(d.getTime())?iso:d.toLocaleString(locale(),{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function relativeUpdate(iso){if(!iso)return '—';const ms=Date.now()-new Date(iso).getTime();if(ms<60000)return t('now');const h=Math.floor(ms/3600000);if(h<24)return t('hours_ago',{n:h});const d=Math.floor(h/24);if(d<7)return t('days_ago',{n:d});return fmtDateTime(iso)}
function isOverdue(t){return !!t.due_date && t.status!=='Done' && t.status!=='Cancelled' && t.due_date < todayISO()}
function daysUntil(iso){if(!iso)return Infinity;const a=new Date(`${todayISO()}T00:00:00`),b=new Date(`${iso}T00:00:00`);return Math.ceil((b-a)/86400000)}
function showToast(msg){el.toast.textContent=msg;el.toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.toast.classList.remove('show'),3500)}
function setSync(text,type=''){el.syncText.textContent=text;el.syncBadge.dataset.state=type}
function setSyncKey(key,type=''){state.syncKey=key;setSync(t(key),type)}
function csvEscape(v){const s=String(v??'');return /[",\r\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s}
function rowsToCsv(rows){return rows.map(r=>r.map(csvEscape).join(',')).join('\n')}
function parseCsv(text){const rows=[];let row=[],field='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(q){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')q=false;else field+=c}else if(c==='"')q=true;else if(c===','){row.push(field);field=''}else if(c==='\n'){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row)}return rows}
function fetchWithTimeout(url,options={},ms=16000){const c=new AbortController();const t=setTimeout(()=>c.abort(),ms);return fetch(url,{...options,signal:c.signal}).finally(()=>clearTimeout(t))}
async function getCsv(room){let err;for(const url of [`${BASE}/_/${encodeURIComponent(room)}/csv?t=${Date.now()}`,`${BASE}/=${encodeURIComponent(room)}.csv?t=${Date.now()}`]){try{const r=await fetchWithTimeout(url,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);return await r.text()}catch(e){err=e}}throw err||new Error(t('read_failed'))}
async function putCsv(room,csv){let err;for(const body of [csv,'\uFEFF'+csv]){try{const r=await fetchWithTimeout(`${BASE}/_/${encodeURIComponent(room)}`,{method:'PUT',cache:'no-store',headers:{'Content-Type':'text/csv;charset=UTF-8'},body},22000);if(!r.ok)throw new Error(`HTTP ${r.status}`);return await r.text()}catch(e){err=e}}throw err||new Error(t('write_failed'))}

function normalizeRecord(obj){const rec={};HEADER.forEach(h=>rec[h]=String(obj[h]??''));if(obj.__scope)rec.__scope=obj.__scope;rec.progress=String(Math.max(0,Math.min(100,Number(rec.progress)||0)));if(rec.record_type==='task'){rec.comments=safeJson(rec.comments_json,[]);rec.history=safeJson(rec.history_json,[]);rec.assigneesList=rec.assignees?rec.assignees.split('|').map(x=>x.trim()).filter(Boolean):[];rec.tagsList=rec.tags?rec.tags.split('|').map(x=>x.trim()).filter(Boolean):[]}if(rec.record_type==='member')rec.extra=safeJson(rec.extra_json,{});if(rec.record_type==='project'){rec.extra=safeJson(rec.extra_json,{});rec.assigneesList=rec.assignees?rec.assignees.split('|').map(x=>x.trim()).filter(Boolean):[]}return rec}
function parseSheet(csv,scope){const rows=parseCsv(csv).filter(r=>r.some(x=>String(x??'').trim()!==''));if(!rows.length)return {records:[],blank:true,safe:true};const header=rows[0].map(x=>String(x??'').trim().toLowerCase());if(!header.includes('record_type')||!header.includes('id'))return {records:[],blank:false,safe:false,header};const ix=h=>header.indexOf(h);const records=rows.slice(1).map(r=>{const o={__scope:scope};HEADER.forEach(h=>o[h]=ix(h)>=0?r[ix(h)]??'':'');return normalizeRecord(o)}).filter(r=>r.id&&r.record_type);return {records,blank:false,safe:true}}
function serializeRecord(r){return HEADER.map(h=>{if(h==='comments_json')return JSON.stringify(r.comments||safeJson(r.comments_json,[]));if(h==='history_json')return JSON.stringify(r.history||safeJson(r.history_json,[]));if(h==='extra_json')return JSON.stringify(r.extra||safeJson(r.extra_json,{}));if(h==='assignees'&&Array.isArray(r.assigneesList))return r.assigneesList.join('|');if(h==='tags'&&Array.isArray(r.tagsList))return r.tagsList.join('|');return r[h]??''})}
function sheetCsv(scope){return rowsToCsv([HEADER,...state.sheets[scope].map(serializeRecord)])}
function seedRecords(scope){const now=nowISO(),out=[];if(scope==='team')DEFAULT_MEMBERS.forEach(m=>out.push(normalizeRecord({__scope:scope,record_type:'member',id:uid(),title:m.code,description:m.name,status:'Active',created_at:now,updated_at:now,extra_json:JSON.stringify({role:m.role})})));if(scope==='projects')DEFAULT_PROJECTS.forEach(([group,name])=>out.push(normalizeRecord({__scope:scope,record_type:'project',id:uid(),title:name,status:'Active',project_group:group,project_name:name,created_at:now,updated_at:now,extra_json:'{}'})));return out}
async function initializeBlank(scope){const seeded=seedRecords(scope);state.sheets[scope]=seeded;await putCsv(SHEETS[scope].room,sheetCsv(scope))}
async function syncAll({notify=false}={}){
  if(state.syncing||state.saving)return;state.syncing=true;setSyncKey('sync_working','');
  try{for(const scope of ['personal','team','projects']){const csv=await getCsv(SHEETS[scope].room);const p=parseSheet(csv,scope);if(!p.safe){state.unsafeSheets.add(scope);continue}state.unsafeSheets.delete(scope);if(p.blank){await initializeBlank(scope)}else state.sheets[scope]=p.records}state.lastSync=nowISO();renderAll();if(state.unsafeSheets.size){setSyncKey('sync_bad_structure','error');if(notify)showToast(t('sync_bad_structure_msg'))}else{setSyncKey('sync_updated','ok');if(notify)showToast(t('sync_success'))}}catch(err){console.error(err);setSyncKey('sync_offline','error');if(notify)showToast(`${t('sync_failed')}: ${err.message}`)}finally{state.syncing=false}
}
async function saveScope(scope,message=t('saved')){
  if(state.unsafeSheets.has(scope)){showToast(t('save_blocked'));return false}state.saving=true;setSyncKey('saving','');
  try{await putCsv(SHEETS[scope].room,sheetCsv(scope));await new Promise(r=>setTimeout(r,700));const p=parseSheet(await getCsv(SHEETS[scope].room),scope);if(!p.safe)throw new Error(t('verify_structure'));const localIds=new Set(state.sheets[scope].map(x=>x.id));const remoteIds=new Set(p.records.map(x=>x.id));if([...localIds].some(id=>!remoteIds.has(id)))throw new Error(t('verify_records'));state.sheets[scope]=p.records;state.lastSync=nowISO();setSyncKey('live_saved','ok');renderAll();showToast(message);return true}catch(err){console.error(err);setSyncKey('save_error','error');showToast(`${t('save_failed')}: ${err.message}`);return false}finally{state.saving=false}
}

function records(scope=state.scope){return scope==='all'?[...state.sheets.personal,...state.sheets.team,...state.sheets.projects]:(state.sheets[scope]||[])}
function tasks(scope=state.scope){return records(scope).filter(r=>r.record_type==='task')}
function resolveTaskScope(task){return task?.__scope||(['personal','team','projects'].includes(state.scope)?state.scope:'personal')}
function findTask(id){return tasks('all').find(x=>x.id===id)}
function scopeLabel(scope){return ({all:t('all'),personal:t('personal'),team:t('team'),projects:t('projects')})[scope]||scope}
function teamMembers(){return state.sheets.team.filter(r=>r.record_type==='member'&&r.status!=='Inactive').map(r=>({id:r.id,code:r.title,name:r.description,role:r.extra?.role||''}))}
function projects(){return state.sheets.projects.filter(r=>r.record_type==='project'&&r.status!=='Archived')}
function memberLabel(code){const m=teamMembers().find(x=>x.code===code);return m?.name?`${m.code} · ${m.name}`:(code||'—')}
function latestComment(task){return [...(task.comments||[])].sort((a,b)=>String(b.at).localeCompare(String(a.at)))[0]}
function changed(task,field,from,to,by='User'){task.history=task.history||[];task.history.push({id:uid(),at:nowISO(),by,field,from:String(from??''),to:String(to??'')})}
function visibleTasks(){let list=[...tasks()];const q=el.searchInput.value.trim().toLowerCase(),status=el.statusFilter.value,owner=el.ownerFilter.value,project=el.projectFilter.value;if(state.scope==='all'&&state.selectedContext!=='all')list=list.filter(t=>t.__scope===state.selectedContext);if(state.scope==='all'&&state.quickFilter==='overdue')list=list.filter(isOverdue);if(state.scope==='all'&&state.quickFilter==='done')list=list.filter(t=>t.status==='Done');if(state.scope==='team'&&state.selectedContext!=='all')list=list.filter(t=>t.owner===state.selectedContext||t.assigneesList.includes(state.selectedContext));if(state.scope==='personal'&&state.quickFilter==='today')list=list.filter(t=>t.start_date===todayISO()||t.due_date===todayISO());if(state.scope==='personal'&&state.quickFilter==='overdue')list=list.filter(isOverdue);if(state.scope==='personal'&&state.quickFilter==='done')list=list.filter(t=>t.status==='Done');if(state.scope==='projects'&&state.selectedContext!=='all')list=list.filter(t=>t.project_name===state.selectedContext||t.project_group===state.selectedContext);if(q)list=list.filter(t=>[t.title,t.description,t.owner,t.project_group,projectGroupLabel(t.project_group),t.project_name,scopeLabel(t.__scope),...t.tagsList,...t.assigneesList].join(' ').toLowerCase().includes(q));if(status)list=list.filter(t=>t.status===status);if(owner)list=list.filter(t=>t.owner===owner||t.assigneesList.includes(owner));if(project)list=list.filter(t=>t.project_name===project);const sort=el.sortSelect.value;list.sort((a,b)=>sort==='due'?(a.due_date||'9999').localeCompare(b.due_date||'9999'):sort==='priority'?(PRIORITY_ORDER[b.priority]||0)-(PRIORITY_ORDER[a.priority]||0):sort==='progress'?Number(b.progress)-Number(a.progress):String(b.updated_at).localeCompare(String(a.updated_at)));return list}

function renderAll(){renderHeader();renderScopeText();renderFilters();renderSummary();renderRail();renderTasks();renderSheetLinks()}
function renderHeader(){
  const all=['personal','team','projects'].flatMap(s=>tasks(s));const open=all.filter(t=>!['Done','Cancelled'].includes(t.status)).length,done=all.filter(t=>t.status==='Done').length,delayed=all.filter(t=>t.status==='Delayed'||t.status==='Blocked'||isOverdue(t)).length,avg=all.length?Math.round(all.reduce((s,t)=>s+Number(t.progress||0),0)/all.length):0;
  el.heroKpis.innerHTML=[[t('active_tasks'),open,t('all_categories'),''],[t('completed'),done,t('done_status'),''],[t('delayed_blocked'),delayed,t('needs_attention'),'is-alert'],[t('avg_progress'),`${avg}%`,t('all_tasks_lower'),'']].map(x=>`<div class="hero-kpi ${x[3]}"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('');
  el.allCount.textContent=countTasksText(all.length);el.personalCount.textContent=countTasksText(tasks('personal').length);el.teamCount.textContent=countTasksText(tasks('team').length);el.projectsCount.textContent=countTasksText(tasks('projects').length)
}
function renderScopeText(){
  const copy={all:[t('panorama'),t('all_tasks_title'),t('all_tasks_subtitle')],personal:[t('personal_upper'),t('my_tasks'),t('personal_subtitle')],team:[t('team_upper'),t('team_tasks'),t('team_subtitle')],projects:[t('projects_upper'),t('project_portfolio'),t('projects_subtitle')]}[state.scope];
  el.scopeEyebrow.textContent=copy[0];el.scopeTitle.textContent=copy[1];el.scopeSubtitle.textContent=copy[2];el.addMember.hidden=!['team','projects'].includes(state.scope);el.addMember.textContent=state.scope==='projects'?t('add_project_member'):t('add_member');el.addProject.hidden=state.scope!=='projects';el.addTask.textContent=state.scope==='all'?t('choose_category'):t('add_task_short')
}
function renderFilters(){
  const current={status:el.statusFilter.value,owner:el.ownerFilter.value,project:el.projectFilter.value};
  el.statusFilter.innerHTML=`<option value="">${t('all_statuses')}</option>`+STATUSES.map(x=>`<option value="${esc(x)}">${esc(statusLabel(x))}</option>`).join('');
  const members=teamMembers();el.ownerFilter.innerHTML=`<option value="">${t('all_owners')}</option>`+members.map(m=>`<option value="${esc(m.code)}">${esc(memberLabel(m.code))}</option>`).join('');
  const ps=projects();el.projectFilter.innerHTML=`<option value="">${t('all_projects')}</option>`+ps.map(p=>`<option value="${esc(p.project_name)}">${esc(projectGroupLabel(p.project_group))} · ${esc(p.project_name)}</option>`).join('');
  if([...el.statusFilter.options].some(o=>o.value===current.status))el.statusFilter.value=current.status;if([...el.ownerFilter.options].some(o=>o.value===current.owner))el.ownerFilter.value=current.owner;if([...el.projectFilter.options].some(o=>o.value===current.project))el.projectFilter.value=current.project
}
function renderSummary(){
  const list=tasks(),active=list.filter(t=>!['Done','Cancelled'].includes(t.status)),open=list.filter(t=>['Backlog','Open'].includes(t.status)).length,prog=list.filter(t=>t.status==='In Progress').length,del=list.filter(t=>t.status==='Delayed'||t.status==='Blocked'||isOverdue(t)).length,done=list.filter(t=>t.status==='Done').length,due=list.filter(t=>{const d=daysUntil(t.due_date);return d>=0&&d<=7&&t.status!=='Done'}).length;
  const cards=[[t('open_backlog'),open,t('to_start'),'open'],[t('in_progress'),prog,t('working'),'progress'],[t('delayed_blocked'),del,t('attention'),'delayed'],[t('done'),done,`${list.length?Math.round(done/list.length*100):0}${t('of_total')}`,'done'],[t('due_7'),due,`${active.length} ${t('active')}`,'due']];
  el.summaryGrid.innerHTML=cards.map(c=>`<article class="summary-card" data-tone="${c[3]}"><div class="summary-top"><span>${c[0]}</span><i></i></div><strong>${c[1]}</strong><small>${c[2]}</small></article>`).join('')
}
function renderRail(){
  let html=`<div class="rail-heading"><h3>${t('focus')}</h3>`+(state.scope==='team'?'<button class="rail-add" data-action="member">+</button>':state.scope==='projects'?'<button class="rail-add" data-action="project">+</button>':'')+'</div><div class="rail-list">';
  html+=`<button class="rail-item ${state.selectedContext==='all'?'active':''}" data-context="all"><span class="avatar">ALL</span><strong>${t('all')}</strong><small>${tasks().length}</small></button>`;
  if(state.scope==='all'){[[t('personal'),'personal'],[t('team'),'team'],[t('projects'),'projects']].forEach(([label,key])=>{const n=tasks('all').filter(x=>x.__scope===key).length;html+=`<button class="rail-item ${state.selectedContext===key?'active':''}" data-context="${key}"><span class="avatar">${label.slice(0,2).toUpperCase()}</span><strong>${label}</strong><small>${n}</small></button>`});[[t('overdue'),'overdue'],[t('done'),'done']].forEach(([label,key])=>html+=`<button class="rail-item" data-quick="${key}"><span class="avatar">${label[0]}</span><strong>${label}</strong><small></small></button>`)}
  else if(state.scope==='personal'){[[t('today'),'today'],[t('overdue'),'overdue'],[t('done'),'done']].forEach(([label,key])=>html+=`<button class="rail-item" data-quick="${key}"><span class="avatar">${label[0]}</span><strong>${label}</strong><small></small></button>`)}
  else if(state.scope==='team'){teamMembers().forEach(m=>{const n=tasks().filter(x=>x.owner===m.code||x.assigneesList.includes(m.code)).length;html+=`<button class="rail-item ${state.selectedContext===m.code?'active':''}" data-context="${esc(m.code)}"><span class="avatar">${esc(m.code)}</span><strong>${esc(m.name||m.code)}</strong><small>${n}</small></button>`})}
  else{PROJECT_GROUPS.forEach(g=>{html+=`<div class="rail-group-title">${esc(projectGroupLabel(g))}</div>`;projects().filter(p=>p.project_group===g).forEach(p=>{const n=tasks().filter(x=>x.project_name===p.project_name).length;html+=`<button class="rail-item ${state.selectedContext===p.project_name?'active':''}" data-context="${esc(p.project_name)}"><span class="avatar">${esc(p.project_name.slice(0,2).toUpperCase())}</span><strong>${esc(p.project_name)}</strong><small>${n}</small></button>`})})}html+='</div>';el.contextRail.innerHTML=html
}
function renderTasks(){const list=visibleTasks();el.taskTableWrap.hidden=state.view!=='table'||!list.length;el.kanbanBoard.hidden=state.view!=='board'||!list.length;el.emptyState.hidden=!!list.length;if(state.view==='table')renderTable(list);else renderKanban(list)}
function renderTable(list){el.taskTable.innerHTML=list.map(task=>{
  const lc=latestComment(task),overdue=isOverdue(task),source=state.scope==='all'?`<span class="scope-badge" data-scope="${esc(task.__scope||'personal')}">${esc(scopeLabel(task.__scope||'personal'))}</span>`:'';
  return `<div class="task-row" data-id="${esc(task.id)}"><div class="task-main" data-open="${esc(task.id)}"><div class="task-titleline">${source}<i class="priority-dot ${esc(task.priority)}"></i><strong>${esc(task.title)}</strong></div><small>${esc(task.project_name?`${projectGroupLabel(task.project_group)} · ${task.project_name}`:(task.tagsList.join(' · ')||task.description||t('no_description')))}</small></div><div class="owner-chip"><span class="owner-avatar">${esc((task.owner||'—').slice(0,3))}</span><span>${esc(memberLabel(task.owner))}</span></div><div><span class="status-chip" data-status="${esc(task.status)}">${esc(statusLabel(task.status||'Open'))}</span></div><div class="progress-cell"><div class="progress-track"><div class="progress-bar" style="width:${Number(task.progress)||0}%"></div></div><span>${Number(task.progress)||0}%</span></div><div class="date-cell">${fmtDate(task.start_date)}</div><div class="date-cell ${overdue?'overdue':''}">${fmtDate(task.due_date)}</div><div class="update-cell">${esc(lc?relativeUpdate(lc.at):relativeUpdate(task.updated_at))}</div><button class="row-menu" data-edit="${esc(task.id)}" title="${esc(t('edit_task_title'))}">⋯</button></div>`
}).join('')}
function renderKanban(list){
  const cols=[[t('backlog_open'),['Backlog','Open']],[t('in_progress'),['In Progress']],[t('waiting_blocked'),['Waiting','Blocked','Delayed']],[t('done'),['Done','Cancelled']]];
  el.kanbanBoard.innerHTML=cols.map(([label,ss])=>{const items=list.filter(task=>ss.includes(task.status));return `<section class="kanban-col"><div class="kanban-head"><strong>${label}</strong><span>${items.length}</span></div><div class="kanban-list">${items.map(task=>`<article class="kanban-card" data-open="${esc(task.id)}"><strong>${state.scope==='all'?`<span class=\"scope-badge inline\" data-scope=\"${esc(task.__scope||'personal')}\">${esc(scopeLabel(task.__scope||'personal'))}</span>`:''}${esc(task.title)}</strong><p>${esc(task.project_name||task.description||t('no_description'))}</p><div class="kanban-card-foot"><span>${esc(task.owner||'—')}</span><span>${Number(task.progress)||0}%</span></div></article>`).join('')}</div></section>`}).join('')
}
function renderSheetLinks(){el.sheetLinks.innerHTML=Object.entries(SHEETS).map(([key,s])=>`<a href="${s.url}" target="_blank" rel="noopener">${esc(({personal:t('sheet_personal'),team:t('sheet_team'),projects:t('sheet_projects')})[key])} ↗</a>`).join('')}

function renderTaskFormOptions(status='Open',priority='Medium',group='',project=''){
  el.taskStatus.innerHTML=STATUSES.map(s=>`<option value="${esc(s)}">${esc(statusLabel(s))}</option>`).join('');el.taskStatus.value=status;
  [...el.taskPriority.options].forEach(o=>o.textContent=priorityLabel(o.value));el.taskPriority.value=priority;
  el.taskProjectGroup.innerHTML='<option value="">—</option>'+PROJECT_GROUPS.map(g=>`<option value="${esc(g)}">${esc(projectGroupLabel(g))}</option>`).join('');el.taskProjectGroup.value=group;updateProjectOptions(project)
}
function populateTaskDialog(task=null){
  if(!task&&state.scope==='all'){showToast(t('choose_scope_new_task'));return}const edit=!!task;el.taskDialogTitle.textContent=edit?t('edit_task_title'):t('new_task');el.taskId.value=task?.id||'';el.taskTitle.value=task?.title||'';el.taskDescription.value=task?.description||'';el.taskProgress.value=Number(task?.progress||0);el.taskStart.value=task?.start_date||todayISO();el.taskDue.value=task?.due_date||'';el.taskTags.value=(task?.tagsList||[]).join(', ');
  const members=teamMembers();el.taskOwner.innerHTML=`<option value="">${t('no_owner')}</option>`+members.map(m=>`<option value="${esc(m.code)}">${esc(memberLabel(m.code))}</option>`).join('');el.taskOwner.value=task?.owner||'';
  el.taskAssignees.innerHTML=members.length?members.map(m=>`<label class="check-chip"><input type="checkbox" value="${esc(m.code)}" ${(task?.assigneesList||[]).includes(m.code)?'checked':''}> ${esc(memberLabel(m.code))}</label>`).join(''):`<span style="font-size:.6rem;color:#8d98a9">${t('no_members_hint')}</span>`;
  renderTaskFormOptions(task?.status||'Open',task?.priority||'Medium',task?.project_group||'',task?.project_name||'');const taskScope=task?resolveTaskScope(task):state.scope;el.taskProjectGroupField.hidden=taskScope!=='projects';el.taskProjectField.hidden=taskScope!=='projects';el.deleteTask.hidden=!edit;el.taskDialog.showModal();setTimeout(()=>el.taskTitle.focus(),30)
}
function updateProjectOptions(selected=''){const group=el.taskProjectGroup.value;const ps=projects().filter(p=>!group||p.project_group===group);el.taskProject.innerHTML=`<option value="">${t('no_project')}</option>`+ps.map(p=>`<option value="${esc(p.project_name)}">${esc(p.project_name)}</option>`).join('');if([...el.taskProject.options].some(o=>o.value===selected))el.taskProject.value=selected}
function openTask(id){const t=findTask(id);if(t)populateTaskDialog(t)}
async function handleTaskSubmit(e){e.preventDefault();const title=el.taskTitle.value.trim();if(!title){showToast(t('title_required_msg'));return}const id=el.taskId.value||uid(),old=findTask(id),now=nowISO(),status=el.taskStatus.value,progress=Math.max(0,Math.min(100,Number(el.taskProgress.value)||0));const selectedAssignees=$$('#taskAssignees input:checked').map(x=>x.value);const tags=el.taskTags.value.split(',').map(x=>x.trim()).filter(Boolean);const targetScope=old?resolveTaskScope(old):state.scope;const rec=normalizeRecord({__scope:targetScope,record_type:'task',id,title,description:el.taskDescription.value.trim(),status,priority:el.taskPriority.value,progress,start_date:el.taskStart.value,due_date:el.taskDue.value,owner:el.taskOwner.value,assignees:selectedAssignees.join('|'),project_group:targetScope==='projects'?el.taskProjectGroup.value:'',project_name:targetScope==='projects'?el.taskProject.value:'',tags:tags.join('|'),created_at:old?.created_at||now,updated_at:now,completed_at:status==='Done'?(old?.completed_at||now):'',comments_json:JSON.stringify(old?.comments||[]),history_json:JSON.stringify(old?.history||[])});if(old){rec.comments=old.comments||[];rec.history=[...(old.history||[])];['title','description','status','priority','progress','start_date','due_date','owner','assignees','project_group','project_name','tags'].forEach(f=>{const ov=f==='tags'?(old.tagsList||[]).join('|'):f==='assignees'?(old.assigneesList||[]).join('|'):old[f],nv=f==='tags'?tags.join('|'):f==='assignees'?selectedAssignees.join('|'):rec[f];if(String(ov??'')!==String(nv??''))changed(rec,f,ov,nv)});if(status==='Done'&&old.status!=='Done')rec.progress='100'}else{rec.comments=[];rec.history=[{id:uid(),at:now,by:'User',field:'created',from:'',to:'created'}]}const idx=state.sheets[targetScope].findIndex(r=>r.id===id);if(idx>=0)state.sheets[targetScope][idx]=rec;else state.sheets[targetScope].push(rec);el.taskDialog.close();renderAll();await saveScope(targetScope,old?t('task_updated'):t('task_added'))}
async function deleteCurrentTask(){const id=el.taskId.value;if(!id)return;const t=findTask(id);if(!t||!confirm(t('delete_confirm',{title:t.title})))return;const scope=resolveTaskScope(t);state.sheets[scope]=state.sheets[scope].filter(r=>r.id!==id);el.taskDialog.close();renderAll();await saveScope(scope,t('task_deleted'))}

function openDetail(id){const task=findTask(id);if(!task)return;state.detailTaskId=id;el.detailTitle.textContent=task.title;const lc=latestComment(task);el.detailMeta.innerHTML=[[t('meta_status'),statusLabel(task.status)],[t('meta_progress'),`${Number(task.progress)||0}%`],[t('meta_owner'),memberLabel(task.owner)],[t('meta_start'),fmtDate(task.start_date)],[t('meta_deadline'),fmtDate(task.due_date)],[t('meta_last_update'),lc?fmtDateTime(lc.at):fmtDateTime(task.updated_at)]].map(([a,b])=>`<div class="meta-card"><span>${a}</span><strong>${esc(b)}</strong></div>`).join('');renderDetailTimelines(task);el.commentProgress.value=task.progress||0;if(!el.detailDialog.open)el.detailDialog.showModal()}
function renderDetailTimelines(task){
  const comments=[...(task.comments||[])].sort((a,b)=>String(b.at).localeCompare(String(a.at)));el.commentTimeline.innerHTML=comments.length?comments.map(c=>`<div class="timeline-item" data-type="${esc(c.type||'note')}"><i class="timeline-dot"></i><div class="timeline-card"><div class="timeline-top"><strong>${esc(commentTypeLabel(c.type))}${c.progress!==''&&c.progress!=null?` · ${Number(c.progress)}%`:''}</strong><time>${esc(fmtDateTime(c.at))}</time></div><p>${esc(c.text)}</p><small>${esc(c.by||t('user'))}</small></div></div>`).join(''):`<div class="timeline-empty">${t('no_updates')}</div>`;
  const history=[...(task.history||[])].sort((a,b)=>String(b.at).localeCompare(String(a.at)));el.historyTimeline.innerHTML=history.length?history.map(h=>`<div class="timeline-item"><i class="timeline-dot"></i><div class="timeline-card"><div class="timeline-top"><strong>${esc(h.field==='created'?t('task_created'):`${t('modified')}: ${fieldLabel(h.field)}`)}</strong><time>${esc(fmtDateTime(h.at))}</time></div>${h.field==='created'?`<p>${esc(t('task_created'))}</p>`:`<p>${esc(historyValue(h.field,h.from))} → ${esc(historyValue(h.field,h.to))}</p>`}<small>${esc(h.by||t('user'))}</small></div></div>`).join(''):`<div class="timeline-empty">${t('no_history')}</div>`
}
async function addComment(e){e.preventDefault();const text=el.commentText.value.trim();if(!text)return;const t=findTask(state.detailTaskId);if(!t)return;const scope=resolveTaskScope(t);const pRaw=el.commentProgress.value,progress=pRaw===''?'':Math.max(0,Math.min(100,Number(pRaw)||0));t.comments=t.comments||[];t.comments.push({id:uid(),at:nowISO(),by:'User',type:el.commentType.value,progress,text});if(progress!==''){if(String(t.progress)!==String(progress))changed(t,'progress',t.progress,progress);t.progress=String(progress);if(progress>0&&['Backlog','Open'].includes(t.status)){changed(t,'status',t.status,'In Progress');t.status='In Progress'}if(progress===100&&t.status!=='Done'){changed(t,'status',t.status,'Done');t.status='Done';t.completed_at=nowISO()}}t.updated_at=nowISO();el.commentText.value='';renderAll();openDetail(t.id);await saveScope(scope,t('progress_added'))}
async function markDone(){const t=findTask(state.detailTaskId);if(!t||t.status==='Done')return;const scope=resolveTaskScope(t);if(t.status!=='Done')changed(t,'status',t.status,'Done');if(String(t.progress)!=='100')changed(t,'progress',t.progress,'100');t.status='Done';t.progress='100';t.completed_at=t.completed_at||nowISO();t.updated_at=nowISO();renderAll();openDetail(t.id);await saveScope(scope,t('marked_done'))}

function openMemberDialog(){el.memberForm.reset();el.memberDialog.showModal();setTimeout(()=>el.memberCode.focus(),30)}
async function addMemberSubmit(e){e.preventDefault();const code=el.memberCode.value.trim().toUpperCase();if(!code)return;if(teamMembers().some(m=>m.code.toUpperCase()===code)){showToast(t('member_exists'));return}const now=nowISO();state.sheets.team.push(normalizeRecord({__scope:'team',record_type:'member',id:uid(),title:code,description:el.memberName.value.trim(),status:'Active',created_at:now,updated_at:now,extra_json:JSON.stringify({role:el.memberRole.value.trim()})}));el.memberDialog.close();renderAll();await saveScope('team',t('member_added'))}
function renderProjectMemberChecks(){el.projectMembers.innerHTML=teamMembers().map(m=>`<label class="check-chip"><input type="checkbox" value="${esc(m.code)}"> ${esc(memberLabel(m.code))}</label>`).join('')||`<span style="font-size:.6rem;color:#8d98a9">${t('add_team_first')}</span>`}
function openProjectDialog(){el.projectForm.reset();el.projectGroup.innerHTML=PROJECT_GROUPS.map(g=>`<option value="${esc(g)}">${esc(projectGroupLabel(g))}</option>`).join('');renderProjectMemberChecks();el.projectDialog.showModal();setTimeout(()=>el.projectName.focus(),30)}
async function addProjectSubmit(e){e.preventDefault();const group=el.projectGroup.value,name=el.projectName.value.trim();if(!name)return;if(projects().some(p=>p.project_group===group&&p.project_name.toLowerCase()===name.toLowerCase())){showToast(t('project_exists'));return}const now=nowISO(),members=$$('#projectMembers input:checked').map(x=>x.value);state.sheets.projects.push(normalizeRecord({__scope:'projects',record_type:'project',id:uid(),title:name,status:'Active',project_group:group,project_name:name,assignees:members.join('|'),created_at:now,updated_at:now,extra_json:'{}'}));el.projectDialog.close();renderAll();await saveScope('projects',t('project_added'))}
function openProjectMemberDialog(){const ps=projects();if(!ps.length){showToast(t('add_project_first'));return}el.projectMemberProject.innerHTML=ps.map(p=>`<option value="${esc(p.id)}">${esc(projectGroupLabel(p.project_group))} · ${esc(p.project_name)}</option>`).join('');const preferred=ps.find(p=>p.project_name===state.selectedContext);if(preferred)el.projectMemberProject.value=preferred.id;renderProjectMemberAssignment();el.projectMemberDialog.showModal()}
function renderProjectMemberAssignment(){const p=projects().find(x=>x.id===el.projectMemberProject.value);const assigned=p?.assigneesList||[];const ms=teamMembers();el.projectMemberChecks.innerHTML=ms.length?ms.map(m=>`<label class="check-chip"><input type="checkbox" value="${esc(m.code)}" ${assigned.includes(m.code)?'checked':''}> ${esc(memberLabel(m.code))}</label>`).join(''):`<span style="font-size:.6rem;color:#8d98a9">${t('add_team_first')}</span>`}
async function projectMemberSubmit(e){e.preventDefault();const p=projects().find(x=>x.id===el.projectMemberProject.value);if(!p)return;const members=$$('#projectMemberChecks input:checked').map(x=>x.value);p.assigneesList=members;p.assignees=members.join('|');p.updated_at=nowISO();p.extra=p.extra||{};p.extra.last_members_update=nowISO();el.projectMemberDialog.close();renderAll();await saveScope('projects',t('project_members_updated'))}

function exportExcel(){
  if(typeof XLSX==='undefined'){showToast(t('excel_unavailable'));return}const list=tasks();
  const rows=list.map(task=>({[t('x_category')]:scopeLabel(task.__scope||state.scope),[t('x_task')]:task.title,[t('x_description')]:task.description,[t('x_status')]:statusLabel(task.status),[t('x_priority')]:priorityLabel(task.priority),[t('x_progress')]:Number(task.progress)||0,[t('x_start')]:task.start_date,[t('x_deadline')]:task.due_date,[t('x_owner')]:task.owner,[t('x_participants')]:task.assigneesList.join(', '),[t('x_project_category')]:projectGroupLabel(task.project_group),[t('x_project')]:task.project_name,[t('x_tags')]:task.tagsList.join(', '),[t('x_created')]:task.created_at,[t('x_updated')]:task.updated_at,[t('x_completed')]:task.completed_at,[t('x_updates')]:(task.comments||[]).length}));
  const wb=XLSX.utils.book_new();const ws=XLSX.utils.json_to_sheet(rows);ws['!cols']=[{wch:13},{wch:34},{wch:45},{wch:15},{wch:12},{wch:11},{wch:12},{wch:12},{wch:14},{wch:28},{wch:24},{wch:22},{wch:26},{wch:22},{wch:22},{wch:22},{wch:14}];XLSX.utils.book_append_sheet(wb,ws,t('x_tasks_sheet').slice(0,31));
  const updates=[];list.forEach(task=>(task.comments||[]).forEach(c=>updates.push({[t('x_category')]:scopeLabel(task.__scope||state.scope),[t('x_task')]:task.title,[t('x_project')]:task.project_name,[t('x_type')]:commentTypeLabel(c.type),[t('x_progress')]:c.progress,[t('x_comment')]:c.text,[t('x_date')]:c.at,[t('x_author')]:c.by||t('user')})));if(updates.length)XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(updates),t('x_comments_sheet').slice(0,31));
  if(state.scope==='team')XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(teamMembers().map(m=>({[t('x_code')]:m.code,[t('x_name')]:m.name,[t('x_role')]:m.role}))),t('x_members_sheet').slice(0,31));
  if(state.scope==='projects')XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(projects().map(p=>({[t('x_category')]:projectGroupLabel(p.project_group),[t('x_project')]:p.project_name,[t('x_members')]:p.assigneesList.join(', '),[t('x_status')]:p.status}))),t('x_projects_sheet').slice(0,31));
  XLSX.writeFile(wb,`taskflow_${state.scope}_${todayISO()}.xlsx`)
}

function switchScope(scope){state.scope=scope;state.selectedContext='all';state.quickFilter='';$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.scope===scope));el.searchInput.value='';el.statusFilter.value='';el.ownerFilter.value='';el.projectFilter.value='';renderAll()}
function bind(){$$('.tab').forEach(b=>b.onclick=()=>switchScope(b.dataset.scope));$$('.view-btn').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;$$('.view-btn').forEach(x=>x.classList.toggle('active',x===b));renderTasks()});[el.searchInput,el.statusFilter,el.ownerFilter,el.projectFilter,el.sortSelect].forEach(x=>x.addEventListener(x.tagName==='INPUT'?'input':'change',renderTasks));[el.addTask,el.openTaskTop,el.emptyAdd].forEach(b=>b.onclick=()=>populateTaskDialog());el.addMember.onclick=()=>state.scope==='projects'?openProjectMemberDialog():openMemberDialog();el.addProject.onclick=openProjectDialog;el.downloadExcel.onclick=exportExcel;el.syncNow.onclick=()=>syncAll({notify:true});el.themeToggle.onclick=toggleTheme;el.languageToggle.onclick=toggleLanguage;el.contextRail.onclick=e=>{const a=e.target.closest('[data-action]'),c=e.target.closest('[data-context]'),q=e.target.closest('[data-quick]');if(a?.dataset.action==='member')openMemberDialog();if(a?.dataset.action==='project')openProjectDialog();if(c){state.selectedContext=c.dataset.context;state.quickFilter='';renderRail();renderTasks()}if(q){state.selectedContext='all';state.quickFilter=q.dataset.quick;el.statusFilter.value='';el.searchInput.value='';if(q.dataset.quick==='overdue')el.sortSelect.value='due';renderRail();renderTasks()}};document.addEventListener('click',e=>{const o=e.target.closest('[data-open]'),ed=e.target.closest('[data-edit]');if(o)openDetail(o.dataset.open);if(ed)openTask(ed.dataset.edit)});el.taskProjectGroup.onchange=()=>updateProjectOptions();el.taskForm.addEventListener('submit',handleTaskSubmit);el.deleteTask.onclick=deleteCurrentTask;el.closeTask.onclick=el.cancelTask.onclick=()=>el.taskDialog.close();el.closeDetail.onclick=()=>el.detailDialog.close();el.commentForm.addEventListener('submit',addComment);el.editFromDetail.onclick=()=>{const id=state.detailTaskId;el.detailDialog.close();openTask(id)};el.doneFromDetail.onclick=markDone;el.memberForm.addEventListener('submit',addMemberSubmit);el.closeMember.onclick=el.cancelMember.onclick=()=>el.memberDialog.close();el.projectForm.addEventListener('submit',addProjectSubmit);el.closeProject.onclick=el.cancelProject.onclick=()=>el.projectDialog.close();el.projectMemberForm.addEventListener('submit',projectMemberSubmit);el.projectMemberProject.onchange=renderProjectMemberAssignment;el.closeProjectMember.onclick=el.cancelProjectMember.onclick=()=>el.projectMemberDialog.close();document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncAll()});window.addEventListener('online',()=>syncAll({notify:true}));setInterval(()=>{if(!document.hidden&&!state.saving)syncAll()},SYNC_MS)}
function boot(){applyStaticTranslations();renderAll();bind();syncAll()}
boot();
